verus! {
    // Specification for the argmax function
    fn argmax(arr: &Vec<i8>) -> (result: usize)
        requires
            // The array must be non-empty
            arr.len() > 0,
        ensures
            // The result must be a valid index within the bounds of the array
            result < arr.len() &&
            // The value at the returned index is the maximum value in the array
            forall|i: usize| (i < arr.len() ==> arr[i] <= arr[result]) &&
            // For all indices strictly less than the returned index, the values are strictly less
            forall|j: usize| (j < result ==> arr[j] < arr[result])
    {
        let mut max_index: usize = 0; // Start with the first index as the maximum
        let mut max_value: i8 = arr[0]; // Start with the first value as the maximum
        let mut idx: usize = 1; // Start checking from the second element

        while idx < arr.len()
            invariant
                idx <= arr.len(),
                max_index < arr.len(),
                max_value == arr[max_index],
                forall|k: usize| (k < idx ==> arr[k] <= max_value),
            decreases arr.len() - idx,
        {
            if arr[idx] > max_value {
                max_value = arr[idx]; // Update the maximum value
                max_index = idx; // Update the index of the maximum value
            }
            idx = idx + 1; // Move to the next index
        }
        max_index // Return the index of the maximum value
    }
}

